"""Reports CSV exporter. Implement export_csv to satisfy TASK.txt."""


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header."""

    def _normalize_columns(columns):
        cols = list(columns)
        for col in cols:
            if not isinstance(col, str):
                raise ValueError("column names must be strings")
        if len(set(cols)) != len(cols):
            raise ValueError("column names must be unique")
        return cols

    def _escape(value):
        text = "" if value is None else str(value)
        if any(ch in text for ch in (",", '"', "\r", "\n")):
            return '"' + text.replace('"', '""') + '"'
        return text

    cols = _normalize_columns(columns)
    lines = [",".join(cols)]
    for row in rows:
        lines.append(",".join(_escape(row.get(col)) for col in cols))
    return "\r\n".join(lines) + "\r\n"
